CREATE TABLE site_content (id TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE projects (id TEXT PRIMARY KEY,title TEXT NOT NULL,category TEXT NOT NULL,location TEXT NOT NULL,description TEXT NOT NULL,image TEXT,published INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE testimonials (id TEXT PRIMARY KEY,name TEXT NOT NULL,role TEXT NOT NULL,company TEXT NOT NULL,quote TEXT NOT NULL,published INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE login_attempts (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, window_end INTEGER NOT NULL);
